tool_input.command:
$endpoints = @("https://hf-mirror.com","https://huggingface.co","https://mirror.ghproxy.com","https://raw.githubusercontent.com")
foreach($e in $endpoints){
  try {
    $r = Measure-Command { try { $resp = Invoke-WebRequest -Uri $e -Method Head -TimeoutSec 12 -ErrorAction Stop; $code = $resp.StatusCode } catch [System.Net.WebException] { $code = "WEBEX:$(($_.Exception.Response).StatusCode)" } catch { $code = "ERR:$($_.Exception.GetType().Name)" } }
    Write-Host "$e -> $code  ($([int]$r.TotalMilliseconds)ms)"
  } catch { Write-Host "$e -> FAIL $($_.Exception.Message)" }
}

tool_input.old_string:
OPT_RE = re.compile(r"(?im)^\s*([A-H])[\.\)、]\s*(.*?)(?=^\s*[A-H][\.\)、]\s*|\Z)")
LETTERS = "ABCDEFGH"

def parse_options(raw: str) -> list[str]:
    parts = OPT_RE.findall(raw)
    if parts:
        # keep declared order (some options may be out of A..H order)
        ordered = sorted(parts, key=lambda p: LETTERS.index(p[0]) if p[0] in LETTERS else 99)
        # de-dup by letter, keep first
        seen = {}
        for letter, text in ordered:
            if letter not in seen:
                seen[letter] = text.strip()
        return [seen[k] for k in sorted(seen) if k in seen]
    # fallback: split on newlines
    chunks = [c.strip() for c in re.split(r"\n+", raw.strip()) if c.strip()]
    return chunks

tool_input.new_string:
# MMVP options look like:  "(a) Open (b) Closed"  (lowercase letters in parens)
OPT_RE = re.compile(r"\(([A-Ha-h])\)\s*(.*?)(?=\([A-Ha-h]\)|\Z)", re.S)
LETTERS = "ABCDEFGH"

def parse_options(raw: str) -> list[str]:
    parts = OPT_RE.findall(raw)
    if parts:
        seen: dict[str, str] = {}
        for letter, text in parts:
            letter = letter.upper()
            if letter not in seen:
                seen[letter] = text.strip()
        if seen:
            return [seen[k] for k in sorted(seen)]
    # fallback: split on newlines / semicolons
    chunks = [c.strip(" ()") for c in re.split(r"[\n;]+", raw.strip()) if c.strip()]
    return chunks
